const raw = $input.item.json || {};
const body = raw.body && typeof raw.body === 'object' ? raw.body : raw;
const batch = Array.isArray(body.events) ? body.events : [body];

const defaultTenantId = String(body.tenantId || $env.DEFAULT_TENANT_ID || 'eds-360');
const defaultTenantName = String(body.tenantName || 'EDS-360 / Emerging Defense Solutions');

const pillarMap = {
  assets:    { scope: 'it',         key: 'it_engineers',        role: 'noc_lead',        department: 'noc',        label: '360 Assets' },
  asset:     { scope: 'it',         key: 'it_engineers',        role: 'noc_lead',        department: 'noc',        label: '360 Assets' },
  endpoints: { scope: 'it',         key: 'devsecops',           role: 'cyber_soc_lead',  department: 'cyber_soc',  label: '360 Endpoints' },
  endpoint:  { scope: 'it',         key: 'devsecops',           role: 'cyber_soc_lead',  department: 'cyber_soc',  label: '360 Endpoints' },
  edr:       { scope: 'it',         key: 'devsecops',           role: 'cyber_soc_lead',  department: 'cyber_soc',  label: '360 Endpoints' },
  people:    { scope: 'department', key: 'hr',                  role: 'department_lead', department: 'hr',         label: '360 People & IAM' },
  identity:  { scope: 'department', key: 'hr',                  role: 'department_lead', department: 'hr',         label: '360 People & IAM' },
  iam:       { scope: 'department', key: 'hr',                  role: 'department_lead', department: 'hr',         label: '360 People & IAM' },
  network:   { scope: 'it',         key: 'networking',          role: 'noc_lead',        department: 'noc',        label: '360 Network & SIEM' },
  siem:      { scope: 'it',         key: 'networking',          role: 'noc_lead',        department: 'noc',        label: '360 Network & SIEM' }
};

const results = [];
for (const ev of batch) {
  if (!ev || typeof ev !== 'object') continue;
  const pillarKey = String(ev.pillar || ev.domain || ev.stream || 'network').trim().toLowerCase();
  const cfg = pillarMap[pillarKey] || pillarMap.network;
  const toolName = String(ev.tool || ev.sourceTool || ev.connector || 'external-toolset');
  const tenantId = String(ev.tenantId || defaultTenantId);
  const tenantName = String(ev.tenantName || defaultTenantName);
  const ref = String(ev.ref || `360-${pillarKey.toUpperCase()}-01`);
  const owner = String(ev.owner || `${toolName} (${cfg.label})`);
  const status = String(ev.status || 'compliant');
  const detail = String(ev.detail || ev.summary || `[${toolName}] ${cfg.label} telemetry update`);

  const kpis = Array.isArray(ev.kpis) && ev.kpis.length > 0 ? ev.kpis : [
    { label: '360 Pillar', value: cfg.label, sub: `Source: ${toolName}`, accent: 'text-cyan-300' },
    { label: 'Last Signal', value: ref, sub: `Tenant: ${tenantId}`, accent: 'text-emerald-300' },
    { label: 'Control Alignment', value: String(ev.control || 'SI.L2-3.14.1'), sub: 'CMMC L2 / CDM mapped', accent: 'text-indigo-300' },
    { label: 'Signal Status', value: status, sub: 'Ingested via n8n bridge', accent: status === 'compliant' ? 'text-emerald-300' : 'text-amber-300' }
  ];

  const items = Array.isArray(ev.items) && ev.items.length > 0 ? ev.items : [
    { ref, owner, detail, status }
  ];

  results.push({
    json: {
      hubPayload: {
        tenantId,
        tenantName,
        scope: ev.scope || cfg.scope,
        key: ev.key || cfg.key,
        sourceLabel: `360-${pillarKey}-${toolName}`,
        kpis,
        items
      },
      rbacHeaders: {
        role: String(ev.role || cfg.role),
        department: String(ev.department || cfg.department)
      }
    }
  });
}

return results;
